    "css": ".recipe-demo {\\n  display: grid;\\n  gap: 16px;\\n  min-width: 0;\\n}\\n\\n.sample-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  gap: 12px;\\n}\\n\\n.sample-card {\\n  min-width: 0;\\n}\\n\\n.sample-button {\\n  appearance: none;\\n  border: 0;\\n  padding: 0;\\n  background: none;\\n  color: inherit;\\n  font: inherit;\\n  cursor: pointer;\\n}\\n.sample-button:focus-visible {\\n  outline: 3px solid var(--primary);\\n  outline-offset: 3px;\\n}\\n.sample-button:disabled, .sample-button[aria-disabled=true] {\\n  opacity: 0.5;\\n  cursor: not-allowed;\\n}\\n.sample-button {\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 8px;\\n  min-height: 44px;\\n  padding-inline: 16px;\\n  border: 1px solid #6366f1;\\n  border-radius: 4px;\\n  font-weight: 600;\\n  background: #6366f1;\\n  color: #fff;\\n  transition: background-color 120ms cubic-bezier(0.2, 0, 0, 1);\\n}\\n@media (prefers-reduced-motion: reduce) {\\n  .sample-button {\\n    transition: none;\\n  }\\n}\\n\\n.sample-note {\\n  transition-duration: 350ms;\\n  transition-timing-function: ease-in;\\n}"
