    "css": ".recipe-demo {\\n  display: grid;\\n  gap: 16px;\\n  min-width: 0;\\n}\\n\\n.sample-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  gap: 12px;\\n}\\n\\n.sample-card {\\n  min-width: 0;\\n}\\n\\n@media not print {\\n  .sample-print-note {\\n    display: none;\\n  }\\n}\\n@media print {\\n  .sample-print-note {\\n    display: block;\\n  }\\n}\\n\\n@media print {\\n  .sample-actions {\\n    display: none;\\n  }\\n  .sample-card {\\n    color: #000;\\n    background: #fff;\\n    box-shadow: none;\\n    break-inside: avoid;\\n  }\\n}"
