    "css": ".recipe-demo {\\n  display: grid;\\n  gap: 16px;\\n  min-width: 0;\\n}\\n\\n.sample-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  gap: 12px;\\n}\\n\\n.sample-card {\\n  min-width: 0;\\n}\\n\\n.sample-primary {\\n  appearance: none;\\n  border: 0;\\n  padding: 0;\\n  background: none;\\n  color: inherit;\\n  font: inherit;\\n  cursor: pointer;\\n}\\n.sample-primary:focus-visible {\\n  outline: 3px solid var(--primary);\\n  outline-offset: 3px;\\n}\\n.sample-primary:disabled, .sample-primary[aria-disabled=true] {\\n  opacity: 0.5;\\n  cursor: not-allowed;\\n}\\n.sample-primary {\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 8px;\\n  min-height: 44px;\\n  padding-inline: 16px;\\n  border: 1px solid #6366f1;\\n  border-radius: 4px;\\n  font-weight: 600;\\n  background: #6366f1;\\n  color: #fff;\\n}\\n\\n.sample-outline {\\n  appearance: none;\\n  border: 0;\\n  padding: 0;\\n  background: none;\\n  color: inherit;\\n  font: inherit;\\n  cursor: pointer;\\n}\\n.sample-outline:focus-visible {\\n  outline: 3px solid var(--primary);\\n  outline-offset: 3px;\\n}\\n.sample-outline:disabled, .sample-outline[aria-disabled=true] {\\n  opacity: 0.5;\\n  cursor: not-allowed;\\n}\\n.sample-outline {\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 8px;\\n  min-height: 44px;\\n  padding-inline: 16px;\\n  border: 1px solid #6366f1;\\n  border-radius: 4px;\\n  font-weight: 600;\\n  background: transparent;\\n  color: var(--text);\\n}\\n\\n.sample-danger {\\n  appearance: none;\\n  border: 0;\\n  padding: 0;\\n  background: none;\\n  color: inherit;\\n  font: inherit;\\n  cursor: pointer;\\n}\\n.sample-danger:focus-visible {\\n  outline: 3px solid var(--primary);\\n  outline-offset: 3px;\\n}\\n.sample-danger:disabled, .sample-danger[aria-disabled=true] {\\n  opacity: 0.5;\\n  cursor: not-allowed;\\n}\\n.sample-danger {\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 8px;\\n  min-height: 32px;\\n  padding-inline: 10px;\\n  border: 1px solid #ef4444;\\n  border-radius: 4px;\\n  font-weight: 600;\\n  background: #ef4444;\\n  color: #0f172a;\\n}"
